 @Test void runtimePolicyOverridesStartupWhileTaskCreationRemainsStartupAuthority(){var r=new RuntimeConfigurationLocalSnapshotRegistry();var v=new RuntimeConfigurationSnapshotValues(r,JsonMapper.builder().build());var a=new RuntimeConfigurationAuthorityRegistry();var p=new TaskOrchestrationProperties();p.setTaskCreationEnabled(false);var view=new TaskDecisionRuntimeConfigurationView(v,a,p);r.atomicSwap(s("{\"core.decision.task-escalation-enabled\":false,\"core.decision.task-min-occurrences\":12,\"core.decision.immediate-task-severities\":\"HIGH,CRITICAL\",\"core.decision.default-routing-policy\":\"CAPABILITY_FIRST\"}"));assertThat(view.taskCreationEnabled()).isFalse();assertThat(view.taskMinOccurrences()).isEqualTo(12);assertThat(view.immediateTaskSeverities()).containsExactlyInAnyOrder("HIGH","CRITICAL");assertThat(view.defaultRoutingPolicy()).isEqualTo("CAPABILITY_FIRST");a.activate(Set.of(TaskDecisionRuntimeConfigurationView.TASK_MIN_OCCURRENCES));r.atomicSwap(s("{}"));assertThatThrownBy(view::taskMinOccurrences).hasMessageContaining("CONFIGURATION_INCOMPLETE");}
